#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

unsigned long long arrMin(unsigned long long *arr, size_t len) {
    unsigned long long p = ULLONG_MAX;
    unsigned long long q = 0;
    for (size_t i = 0; i < len; i++) {
        q = arr[i];
        if (q < p) {
            p = q;
        }
    }
    return p;
}

int main() {
    unsigned long long test1[] = {5, 2, 8, 1, 9};
    printf("%llu\n", arrMin(test1, 5));

    unsigned long long test2[] = {100};
    printf("%llu\n", arrMin(test2, 1));

    unsigned long long test3[] = {0, 0, 0};
    printf("%llu\n", arrMin(test3, 3));

    unsigned long long test4[] = {ULLONG_MAX, ULLONG_MAX - 1};
    printf("%llu\n", arrMin(test4, 2));

    unsigned long long test5[] = {42, 7, 42, 7, 42};
    printf("%llu\n", arrMin(test5, 5));

    return 0;
}

