        for (int i = 1; i < arr.length; i++) {
            if (arr[i] < p) {
                q = p;
                p = arr[i];
            }
        }
        return p;
    }

    public static void main(String[] args) {
        // Test 1: Basic case
        long[] arr1 = {5, 3, 9, 1, 7};
        System.out.println(arrMin(arr1));

        // Test 2: Single element
        long[] arr2 = {42};
        System.out.println(arrMin(arr2));

        // Test 3: All same values
        long[] arr3 = {8, 8, 8, 8};
        System.out.println(arrMin(arr3));

        // Test 4: Contains zero
        long[] arr4 = {10, 0, 5, 3};
        System.out.println(arrMin(arr4));

